/* ════════════════════════════════════════════
   CSS Custom Properties — Light & Dark themes
   ════════════════════════════════════════════ */
:root {
  --bg:           #f0f2f5;
  --surface:      #ffffff;
  --surface-alt:  #f7f8fa;
  --border:       #e2e5ea;
  --text:         #1a1d23;
  --text-muted:   #6b7280;
  --primary:      #4f6ef7;
  --primary-dark: #3a58e0;
  --primary-light:#eef0fe;
  --danger:       #ef4444;
  --danger-light: #fef2f2;
  --success:      #22c55e;
  --radius:       12px;
  --radius-sm:    8px;
  --shadow:       0 2px 12px rgba(0,0,0,.07);
  --shadow-lg:    0 6px 24px rgba(0,0,0,.12);
  --transition:   .18s ease;
  --font:         'Segoe UI', system-ui, -apple-system, sans-serif;
}

[data-theme="dark"] {
  --bg:           #0f1117;
  --surface:      #1a1d27;
  --surface-alt:  #22263a;
  --border:       #2e3347;
  --text:         #e8eaf2;
  --text-muted:   #8b92ab;
  --primary:      #6b82fa;
  --primary-dark: #5068e0;
  --primary-light:#1e2240;
  --danger:       #f87171;
  --danger-light: #2a1a1a;
  --shadow:       0 2px 12px rgba(0,0,0,.4);
  --shadow-lg:    0 6px 24px rgba(0,0,0,.5);
}

/* ════════════════════════════════════════════
   Reset & Base
   ════════════════════════════════════════════ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  font-size: 15px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background var(--transition), color var(--transition);
}

ul { list-style: none; }
a  { color: var(--primary); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; font-family: inherit; }
input, textarea, select { font-family: inherit; }

/* ════════════════════════════════════════════
   Top Bar
   ════════════════════════════════════════════ */
.topbar {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 56px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow);
  transition: background var(--transition), border-color var(--transition);
}

.app-logo {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: .02em;
  color: var(--primary);
}

.icon-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 1rem;
  color: var(--text);
  transition: background var(--transition), border-color var(--transition);
}
.icon-btn:hover { background: var(--surface-alt); }

/* ════════════════════════════════════════════
   Layout
   ════════════════════════════════════════════ */
.layout {
  max-width: 960px;
  margin: 0 auto;
  padding: 28px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 640px) {
  .two-col { grid-template-columns: 1fr; }
  .topbar  { padding: 0 14px; }
  .layout  { padding: 16px 12px 40px; }
}

/* ════════════════════════════════════════════
   Card
   ════════════════════════════════════════════ */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: background var(--transition), border-color var(--transition);
}

.card-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text);
}

/* ════════════════════════════════════════════
   Buttons
   ════════════════════════════════════════════ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-alt);
  color: var(--text);
  font-size: .9rem;
  font-weight: 500;
  transition: background var(--transition), opacity var(--transition),
              border-color var(--transition), transform .1s;
}
.btn:hover:not(:disabled) { background: var(--border); }
.btn:active:not(:disabled) { transform: scale(.97); }
.btn:disabled { opacity: .45; cursor: not-allowed; }

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}
.btn.primary:hover:not(:disabled) { background: var(--primary-dark); border-color: var(--primary-dark); }

.btn.ghost {
  background: none;
  border-color: transparent;
  color: var(--text-muted);
}
.btn.ghost:hover { background: var(--surface-alt); color: var(--text); }

.btn.small { padding: 5px 11px; font-size: .82rem; }
.btn.danger { background: var(--danger-light); border-color: var(--danger); color: var(--danger); }
.btn.danger:hover:not(:disabled) { background: var(--danger); color: #fff; }

/* ════════════════════════════════════════════
   Greeting Card
   ════════════════════════════════════════════ */
.greeting-card {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.greeting-text { flex: 1 1 240px; }

#greetingMsg {
  font-size: 1.8rem;
  font-weight: 800;
  line-height: 1.2;
  color: var(--text);
}

.greeting-sub {
  margin-top: 4px;
  font-size: 1rem;
  color: var(--text-muted);
  min-height: 1.4em;
}

.datetime-block {
  text-align: right;
  flex-shrink: 0;
}

.clock {
  font-size: 2.4rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: .04em;
  color: var(--primary);
}

.date-text {
  font-size: .9rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.name-editor {
  display: none;
  align-items: center;
  gap: 8px;
  flex-basis: 100%;
  flex-wrap: wrap;
  margin-top: 4px;
}
.name-editor.open { display: flex; }
.name-editor input {
  flex: 1 1 160px;
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-alt);
  color: var(--text);
  font-size: .9rem;
  outline: none;
  transition: border-color var(--transition);
}
.name-editor input:focus { border-color: var(--primary); }

.name-edit-trigger {
  margin-top: 8px;
  font-size: .78rem;
}

/* ════════════════════════════════════════════
   Focus Timer
   ════════════════════════════════════════════ */
.timer-card { display: flex; flex-direction: column; align-items: center; text-align: center; }

.timer-display {
  font-size: 4rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: .06em;
  color: var(--primary);
  margin: 8px 0 16px;
}

.timer-modes {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 16px;
}

.mode-btn {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 5px 14px;
  font-size: .8rem;
  font-weight: 500;
  color: var(--text-muted);
  transition: background var(--transition), color var(--transition);
}
.mode-btn:hover   { background: var(--primary-light); color: var(--primary); }
.mode-btn.active  { background: var(--primary); border-color: var(--primary); color: #fff; }

.timer-controls { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; }

.timer-status {
  margin-top: 12px;
  font-size: .82rem;
  color: var(--text-muted);
  min-height: 1.2em;
}

/* ════════════════════════════════════════════
   Quick Links
   ════════════════════════════════════════════ */
.links-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
  max-height: 220px;
  overflow-y: auto;
}

.link-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--surface-alt);
  border: 1px solid var(--border);
  transition: background var(--transition);
}
.link-item:hover { background: var(--primary-light); }

.link-favicon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  border-radius: 3px;
}

.link-item a {
  flex: 1;
  font-size: .88rem;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text);
}
.link-item a:hover { color: var(--primary); text-decoration: none; }

.link-del {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: .8rem;
  padding: 2px 4px;
  border-radius: 4px;
  opacity: .5;
  transition: opacity var(--transition), color var(--transition);
}
.link-del:hover { opacity: 1; color: var(--danger); }

.link-form {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.link-form input {
  flex: 1 1 100px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-alt);
  color: var(--text);
  font-size: .85rem;
  outline: none;
  transition: border-color var(--transition);
}
.link-form input:focus { border-color: var(--primary); }

.field-error {
  font-size: .78rem;
  color: var(--danger);
  margin-top: 6px;
  min-height: 1em;
}

/* ════════════════════════════════════════════
   To-Do List
   ════════════════════════════════════════════ */
.todo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.todo-header .card-title { margin-bottom: 0; }

.todo-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.todo-controls select {
  padding: 5px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-alt);
  color: var(--text);
  font-size: .82rem;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition);
}
.todo-controls select:focus { border-color: var(--primary); }

.todo-form {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
}
.todo-form input {
  flex: 1;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-alt);
  color: var(--text);
  font-size: .9rem;
  outline: none;
  transition: border-color var(--transition);
}
.todo-form input:focus { border-color: var(--primary); }

.todo-list { display: flex; flex-direction: column; gap: 6px; }

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-alt);
  transition: background var(--transition), opacity var(--transition);
  animation: fadeIn .18s ease;
}
.todo-item.done { opacity: .55; }
.todo-item.done .todo-text { text-decoration: line-through; color: var(--text-muted); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Custom checkbox */
.todo-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid var(--border);
  border-radius: 5px;
  flex-shrink: 0;
  cursor: pointer;
  position: relative;
  transition: border-color var(--transition), background var(--transition);
}
.todo-checkbox:checked {
  background: var(--primary);
  border-color: var(--primary);
}
.todo-checkbox:checked::after {
  content: '✓';
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
}

.todo-text {
  flex: 1;
  font-size: .9rem;
  word-break: break-word;
  outline: none;
}
.todo-text[contenteditable="true"] {
  border-bottom: 1px dashed var(--primary);
  padding-bottom: 1px;
}

.todo-actions { display: flex; gap: 4px; flex-shrink: 0; }

.todo-btn {
  background: none;
  border: none;
  font-size: .8rem;
  padding: 3px 6px;
  border-radius: 4px;
  color: var(--text-muted);
  transition: color var(--transition), background var(--transition);
}
.todo-btn:hover { background: var(--border); color: var(--text); }
.todo-btn.del:hover  { background: var(--danger-light); color: var(--danger); }

.empty-hint {
  text-align: center;
  color: var(--text-muted);
  font-size: .88rem;
  padding: 20px 0 4px;
}

/* ════════════════════════════════════════════
   Toast
   ════════════════════════════════════════════ */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--text);
  color: var(--bg);
  padding: 10px 20px;
  border-radius: 24px;
  font-size: .86rem;
  font-weight: 500;
  opacity: 0;
  pointer-events: none;
  transition: opacity .22s, transform .22s;
  white-space: nowrap;
  z-index: 999;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ════════════════════════════════════════════
   Scrollbar styling (Webkit)
   ════════════════════════════════════════════ */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ════════════════════════════════════════════
   Dashboard — app.js
   Vanilla JS · LocalStorage · No frameworks
   ════════════════════════════════════════════ */

'use strict';

/* ──────────────────────────────────────────
   Utility: localStorage helpers
   ────────────────────────────────────────── */
const store = {
  get:    (key, fallback = null) => { try { const v = localStorage.getItem(key); return v !== null ? JSON.parse(v) : fallback; } catch { return fallback; } },
  set:    (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} },
  remove: (key) => localStorage.removeItem(key),
};

/* ──────────────────────────────────────────
   Utility: toast notification
   ────────────────────────────────────────── */
const toastEl = document.getElementById('toast');
let toastTimer;
function showToast(msg, duration = 2200) {
  clearTimeout(toastTimer);
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), duration);
}

/* ══════════════════════════════════════════
   1. THEME (Dark Mode)
   ══════════════════════════════════════════ */
const themeToggle = document.getElementById('themeToggle');
let currentTheme = store.get('theme', 'light');

function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  themeToggle.textContent = theme === 'dark' ? '☀️' : '🌙';
  themeToggle.setAttribute('title', theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode');
  themeToggle.setAttribute('aria-label', themeToggle.getAttribute('title'));
  store.set('theme', theme);
}

applyTheme(currentTheme);

themeToggle.addEventListener('click', () => {
  currentTheme = currentTheme === 'dark' ? 'light' : 'dark';
  applyTheme(currentTheme);
  showToast(currentTheme === 'dark' ? '🌙 Dark mode on' : '☀️ Light mode on');
});

/* ══════════════════════════════════════════
   2. GREETING, CLOCK & DATE
   ══════════════════════════════════════════ */
const greetingMsg  = document.getElementById('greetingMsg');
const greetingSub  = document.getElementById('greetingName');
const clockDisplay = document.getElementById('clockDisplay');
const dateDisplay  = document.getElementById('dateDisplay');
const nameEditor   = document.getElementById('nameEditor');
const nameInput    = document.getElementById('nameInput');
const nameSaveBtn  = document.getElementById('nameSaveBtn');
const nameCancelBtn= document.getElementById('nameCancelBtn');
const editNameBtn  = document.getElementById('editNameBtn');

let userName = store.get('userName', '');

function getGreeting(hour) {
  if (hour <  5) return 'Good night';
  if (hour < 12) return 'Good morning';
  if (hour < 17) return 'Good afternoon';
  if (hour < 21) return 'Good evening';
  return 'Good night';
}

function pad(n) { return String(n).padStart(2, '0'); }

function updateClock() {
  const now  = new Date();
  const h    = now.getHours();
  const m    = now.getMinutes();
  const s    = now.getSeconds();
  clockDisplay.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;

  const days   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  dateDisplay.textContent = `${days[now.getDay()]}, ${months[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;

  const greeting = getGreeting(h);
  greetingMsg.textContent = userName ? `${greeting}, ${userName}!` : `${greeting}!`;
  greetingSub.textContent = userName ? `Welcome back 👋` : `Set your name below ↓`;
}

updateClock();
setInterval(updateClock, 1000);

// Name editing
editNameBtn.addEventListener('click', () => {
  nameInput.value = userName;
  nameEditor.classList.add('open');
  nameInput.focus();
  editNameBtn.style.display = 'none';
});

function saveName() {
  const val = nameInput.value.trim();
  userName = val;
  store.set('userName', userName);
  nameEditor.classList.remove('open');
  editNameBtn.style.display = '';
  updateClock();
  showToast(userName ? `👋 Hello, ${userName}!` : 'Name cleared.');
}

nameSaveBtn.addEventListener('click', saveName);
nameCancelBtn.addEventListener('click', () => {
  nameEditor.classList.remove('open');
  editNameBtn.style.display = '';
});
nameInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') saveName();
  if (e.key === 'Escape') nameCancelBtn.click();
});

/* ══════════════════════════════════════════
   3. FOCUS TIMER
   ══════════════════════════════════════════ */
const timerDisplay  = document.getElementById('timerDisplay');
const timerStart    = document.getElementById('timerStart');
const timerStop     = document.getElementById('timerStop');
const timerReset    = document.getElementById('timerReset');
const timerStatus   = document.getElementById('timerStatus');
const modeButtons   = document.querySelectorAll('.mode-btn');

let timerSeconds    = 25 * 60;
let timerInterval   = null;
let timerRunning    = false;
let timerDuration   = 25 * 60; // current mode default

function formatTime(secs) {
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${pad(m)}:${pad(s)}`;
}

function updateTimerDisplay() {
  timerDisplay.textContent = formatTime(timerSeconds);
  document.title = timerRunning ? `${formatTime(timerSeconds)} — Dashboard` : 'Dashboard';
}

function setMode(minutes, btn) {
  stopTimer();
  timerDuration = minutes * 60;
  timerSeconds  = timerDuration;
  modeButtons.forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  timerStatus.textContent = '';
  updateTimerDisplay();
}

modeButtons.forEach(btn => {
  btn.addEventListener('click', () => setMode(Number(btn.dataset.minutes), btn));
});

function startTimer() {
  if (timerRunning) return;
  if (timerSeconds === 0) { timerSeconds = timerDuration; }
  timerRunning = true;
  timerStart.disabled = true;
  timerStop.disabled  = false;
  timerStatus.textContent = 'Focus! 🔥';

  timerInterval = setInterval(() => {
    timerSeconds--;
    updateTimerDisplay();
    if (timerSeconds <= 0) {
      clearInterval(timerInterval);
      timerRunning = false;
      timerStart.disabled = false;
      timerStop.disabled  = true;
      timerStatus.textContent = '🎉 Time\'s up! Great job.';
      document.title = 'Dashboard';
      showToast('⏰ Timer finished!', 3000);
      // Simple audio cue using Web Audio API
      playBeep();
    }
  }, 1000);
}

function stopTimer() {
  clearInterval(timerInterval);
  timerRunning = false;
  timerStart.disabled = false;
  timerStop.disabled  = true;
  if (timerSeconds > 0 && timerSeconds < timerDuration) {
    timerStatus.textContent = 'Paused ⏸';
  }
  document.title = 'Dashboard';
}

function resetTimer() {
  stopTimer();
  timerSeconds = timerDuration;
  timerStatus.textContent = '';
  updateTimerDisplay();
}

timerStart.addEventListener('click', startTimer);
timerStop.addEventListener('click', stopTimer);
timerReset.addEventListener('click', resetTimer);

function playBeep() {
  try {
    const ctx  = new (window.AudioContext || window.webkitAudioContext)();
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = 880;
    osc.type = 'sine';
    gain.gain.setValueAtTime(.4, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime + .8);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + .8);
  } catch { /* AudioContext not available */ }
}

updateTimerDisplay();

/* ══════════════════════════════════════════
   4. TO-DO LIST
   ══════════════════════════════════════════ */
const todoForm    = document.getElementById('todoForm');
const todoInput   = document.getElementById('todoInput');
const todoList    = document.getElementById('todoList');
const todoEmpty   = document.getElementById('todoEmpty');
const sortSelect  = document.getElementById('sortSelect');
const clearDoneBtn= document.getElementById('clearDoneBtn');

let todos = store.get('todos', []);

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function saveTodos() {
  store.set('todos', todos);
}

function getSortedTodos() {
  const sorted = [...todos];
  const mode   = sortSelect.value;
  switch (mode) {
    case 'newest':  return sorted.sort((a, b) => b.createdAt - a.createdAt);
    case 'oldest':  return sorted.sort((a, b) => a.createdAt - b.createdAt);
    case 'az':      return sorted.sort((a, b) => a.text.localeCompare(b.text));
    case 'za':      return sorted.sort((a, b) => b.text.localeCompare(a.text));
    case 'pending': return sorted.sort((a, b) => Number(a.done) - Number(b.done));
    case 'done':    return sorted.sort((a, b) => Number(b.done) - Number(a.done));
    default:        return sorted;
  }
}

function renderTodos() {
  todoList.innerHTML = '';
  const sorted = getSortedTodos();

  if (sorted.length === 0) {
    todoEmpty.hidden = false;
    return;
  }
  todoEmpty.hidden = true;

  sorted.forEach(todo => {
    const li = document.createElement('li');
    li.className = `todo-item${todo.done ? ' done' : ''}`;
    li.dataset.id = todo.id;

    // Checkbox
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.className = 'todo-checkbox';
    cb.checked = todo.done;
    cb.setAttribute('aria-label', `Mark "${todo.text}" as ${todo.done ? 'pending' : 'done'}`);
    cb.addEventListener('change', () => toggleTodo(todo.id));

    // Text (contenteditable for inline editing)
    const span = document.createElement('span');
    span.className = 'todo-text';
    span.textContent = todo.text;
    span.setAttribute('role', 'textbox');
    span.setAttribute('aria-label', 'Task text');
    // Double-click to edit
    span.addEventListener('dblclick', () => startEditTodo(span, todo.id));
    span.addEventListener('keydown', (e) => {
      if (!span.isContentEditable) return;
      if (e.key === 'Enter') { e.preventDefault(); finishEditTodo(span, todo.id); }
      if (e.key === 'Escape') { span.textContent = todo.text; span.contentEditable = 'false'; }
    });
    span.addEventListener('blur', () => {
      if (span.isContentEditable) finishEditTodo(span, todo.id);
    });

    // Action buttons
    const actions = document.createElement('div');
    actions.className = 'todo-actions';

    const editBtn = document.createElement('button');
    editBtn.className = 'todo-btn';
    editBtn.textContent = '✏️';
    editBtn.setAttribute('aria-label', `Edit task: ${todo.text}`);
    editBtn.title = 'Edit';
    editBtn.addEventListener('click', () => startEditTodo(span, todo.id));

    const delBtn = document.createElement('button');
    delBtn.className = 'todo-btn del';
    delBtn.textContent = '🗑';
    delBtn.setAttribute('aria-label', `Delete task: ${todo.text}`);
    delBtn.title = 'Delete';
    delBtn.addEventListener('click', () => deleteTodo(todo.id));

    actions.append(editBtn, delBtn);
    li.append(cb, span, actions);
    todoList.appendChild(li);
  });
}

function startEditTodo(span, id) {
  span.contentEditable = 'true';
  span.focus();
  // Move caret to end
  const range = document.createRange();
  range.selectNodeContents(span);
  range.collapse(false);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

function finishEditTodo(span, id) {
  const newText = span.textContent.trim();
  span.contentEditable = 'false';
  if (!newText) {
    const todo = todos.find(t => t.id === id);
    span.textContent = todo ? todo.text : '';
    return;
  }
  const todo = todos.find(t => t.id === id);
  if (todo && todo.text !== newText) {
    todo.text = newText;
    saveTodos();
    showToast('✏️ Task updated.');
  }
}

function toggleTodo(id) {
  const todo = todos.find(t => t.id === id);
  if (todo) {
    todo.done = !todo.done;
    saveTodos();
    renderTodos();
    if (todo.done) showToast('✅ Task completed!');
  }
}

function deleteTodo(id) {
  todos = todos.filter(t => t.id !== id);
  saveTodos();
  renderTodos();
  showToast('🗑 Task deleted.');
}

todoForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = todoInput.value.trim();
  if (!text) return;
  todos.push({ id: genId(), text, done: false, createdAt: Date.now() });
  saveTodos();
  renderTodos();
  todoInput.value = '';
  todoInput.focus();
  showToast('📝 Task added!');
});

sortSelect.addEventListener('change', renderTodos);

clearDoneBtn.addEventListener('click', () => {
  const count = todos.filter(t => t.done).length;
  if (count === 0) { showToast('No completed tasks to clear.'); return; }
  todos = todos.filter(t => !t.done);
  saveTodos();
  renderTodos();
  showToast(`🗑 Cleared ${count} completed task${count > 1 ? 's' : ''}.`);
});

renderTodos();

