    const img = document.createElement('img');
    img.className = 'link-favicon';
    img.src = getFaviconUrl(link.url);
    img.alt = '';
    img.onerror = () => { img.style.display = 'none'; };

    const a = document.createElement('a');
    a.href   = link.url;
    a.target = '_blank';
